// 11-12 (Kido: use the pines the snow thread found): Sketchfab Japanese Black Pine (matt z chan, CC BY 4.0) and the
// tree pack prefabs, imported by the snow thread under SnowPlague/ThirdParty/Trees. That folder is regenerated by the
// snow builder, so 폐촌 never edits it: the materials are copied once to AbandonedVillage/ThirdParty/Trees/Materials
// with the snow turned off, and each placed tree is unpacked and pointed at those copies. Meshes stay referenced.
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;

public static partial class AVBuilder
{
    const string SnowTrees = "Assets/Game/SnowPlague/ThirdParty/Trees/";
    const string AVTreeMats = Root + "/ThirdParty/Trees/Materials";
    static readonly Dictionary<string, Material> treeMats = new Dictionary<string, Material>();

    static Material AVTreeMat(Material src)
    {
        if (!src) return src;
        if (treeMats.TryGetValue(src.name, out var m) && m) return m;
        if (!AssetDatabase.IsValidFolder(Root + "/ThirdParty/Trees")) AssetDatabase.CreateFolder(Root + "/ThirdParty", "Trees");
        if (!AssetDatabase.IsValidFolder(AVTreeMats)) AssetDatabase.CreateFolder(Root + "/ThirdParty/Trees", "Materials");
        var path = $"{AVTreeMats}/AV_{src.name}.mat";
        m = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (!m) { m = new Material(src); AssetDatabase.CreateAsset(m, path); }
        else m.CopyPropertiesFromMaterial(src);
        foreach (var p in new[] { "_SnowCover", "_SnowClump" }) if (m.HasProperty(p)) m.SetFloat(p, 0f);
        // 11-12 Kido: needles far too green -> mostly desaturated, darker, a little olive; see-through hole near the player
        if (m.HasProperty("_Desat")) m.SetFloat("_Desat", 0.8f);
        if (m.HasProperty("_Tint")) m.SetColor("_Tint", src.GetColor("_Tint") * new Color(0.85f, 0.78f, 0.74f, 1f));
        SeeThroughOn(m);
        EditorUtility.SetDirty(m);
        return treeMats[src.name] = m;
    }

    static void SeeThroughOn(Material m)
    {
        if (!m.HasProperty("_SeeThrough")) return;
        m.SetFloat("_SeeThrough", 1f); m.EnableKeyword("SP_SEETHROUGH"); EditorUtility.SetDirty(m);
    }

    // the kit dead trees (Lit) get SnowPlague/Vegetation copies of their bark and twig materials so they also open up
    static Material seeBark, seeTwig;
    static void SeeThroughKitTree(GameObject go)
    {
        var sh = Shader.Find("SnowPlague/Vegetation");
        if (!go || !sh) return;
        Material Make(string name, Material from, bool twoSided)
        {
            var path = $"{AVTreeMats}/{name}.mat";
            if (!AssetDatabase.IsValidFolder(Root + "/ThirdParty/Trees")) AssetDatabase.CreateFolder(Root + "/ThirdParty", "Trees");
            if (!AssetDatabase.IsValidFolder(AVTreeMats)) AssetDatabase.CreateFolder(Root + "/ThirdParty/Trees", "Materials");
            var m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (!m) { m = new Material(sh); AssetDatabase.CreateAsset(m, path); }
            m.shader = sh;
            m.SetTexture("_BaseMap", from.GetTexture("_BaseMap")); m.SetTextureScale("_BaseMap", from.GetTextureScale("_BaseMap"));
            var n = from.GetTexture("_BumpMap"); m.SetTexture("_BumpMap", n); m.SetFloat("_UseNormal", n ? 1f : 0f);
            m.SetColor("_Tint", from.GetColor("_BaseColor") * 0.85f); m.SetFloat("_Desat", 0.5f);
            m.SetFloat("_Bend", 0f); m.SetFloat("_SnowCover", 0f); m.SetFloat("_SnowClump", 0f); m.SetFloat("_SnowBias", -1f);
            m.SetFloat("_Cull", twoSided ? 0f : 2f);
            SeeThroughOn(m);
            return m;
        }
        if (!seeBark) seeBark = Make("AV_SeeBark", mats["AV_Bark"], false);
        if (!seeTwig) seeTwig = Make("AV_SeeTwig", mats["AV_Twig"], true);
        foreach (var r in go.GetComponentsInChildren<Renderer>())
        {
            var ms = r.sharedMaterials;
            for (int i = 0; i < ms.Length; i++) ms[i] = ms[i] == mats["AV_Bark"] ? seeBark : ms[i] == mats["AV_Twig"] ? seeTwig : ms[i];
            r.sharedMaterials = ms;
        }
    }

    static GameObject PlaceTree(string prefab, Vector3 pos, float yaw, float scale, Transform parent, bool shadows = false)
    {
        var src = AssetDatabase.LoadAssetAtPath<GameObject>(SnowTrees + "Prefabs/" + prefab + ".prefab");
        if (!src) { Debug.LogWarning("[AV] missing tree " + prefab); return null; }
        var go = (GameObject)PrefabUtility.InstantiatePrefab(src, parent ? parent : root);
        PrefabUtility.UnpackPrefabInstance(go, PrefabUnpackMode.Completely, InteractionMode.AutomatedAction);
        go.name = prefab;
        go.transform.SetPositionAndRotation(pos, Quaternion.Euler(0, yaw, 0));
        go.transform.localScale = Vector3.one * scale;
        foreach (var r in go.GetComponentsInChildren<Renderer>())
        {
            var ms = r.sharedMaterials;
            for (int i = 0; i < ms.Length; i++) ms[i] = AVTreeMat(ms[i]);
            r.sharedMaterials = ms;
            r.shadowCastingMode = shadows ? UnityEngine.Rendering.ShadowCastingMode.On : UnityEngine.Rendering.ShadowCastingMode.Off;
        }
        foreach (var c in go.GetComponentsInChildren<Collider>()) Object.DestroyImmediate(c);
        GameObjectUtility.SetStaticEditorFlags(go, StaticEditorFlags.BatchingStatic);
        return go;
    }

    // a few hero pines where the camera can see them, cheaper pines and snags along the edges
    static void BuildPines(System.Func<float, float, float> G)
    {
        if (!AssetDatabase.IsValidFolder(SnowTrees + "Prefabs")) { Debug.LogWarning("[AV] snow tree prefabs not found"); return; }
        var pines = Group("Pines");
        Vector3 At(float x, float z) => new Vector3(x, G(x, z) - 0.1f, z);
        // hero pines (156k tris each): 11-12 Kido "no trees inside the field" -> three just outside the arena corners
        foreach (var p in new[] { new Vector2(-49.5f, 39.5f), new Vector2(49.5f, 38f), new Vector2(49.5f, -46.5f) })
            PlaceTree(rng.NextDouble() < 0.5 ? "TR_HeroPine_A" : "TR_HeroPine_B", At(p.x, p.y), R(0, 360), R(0.9f, 1.15f), pines, true);
        // (no hero pines on the south bank: the camera sits right above it and their canopy filled the frame, 11-12)
        // cheaper pines and dead conifers between the side house rows and on the north terrace edge
        string[] edge = { "TR_Pine", "TR_DeadConifer_A", "TR_Snag_A", "TR_Pine", "TR_DeadConifer_B", "TR_Snag_C" };
        int i = 0;
        foreach (float sx in new[] { -1f, 1f })
            for (float z = -40f; z <= 36f; z += R(16f, 22f))
                PlaceTree(edge[i++ % edge.Length], At(sx * R(48f, 50f), z), R(0, 360), R(0.9f, 1.3f), pines);
        for (float x = -60f; x <= 60f; x += R(14f, 20f))
            PlaceTree(edge[i++ % edge.Length].Replace("TR_Pine", "TR_Snag_B"), At(x, R(-62f, -58f)), R(0, 360), R(0.8f, 1.1f), pines);
    }
}
